    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(true);
        address asserter = address(c.optimisticAsserter());
        bool reverted;
        if (asserter == address(this)) {
            // As the optimistic asserter, the call must succeed.
            c.requestPrice(identifier, time, ancillaryData);
            reverted = false;
        } else {
            // Any other caller must be rejected.
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        assert(reverted == (asserter != address(this)));
    }

    receive() external payable {}
}

