contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, bool truthfully, bytes32 identifier, uint256 time) public payable {
        require(true);

        // dispute should always be allowed regardless of inputs
        bool allowed = c.isDisputeAllowed(assertionId, address(this));
        assert(allowed);

        // callback from anyone other than the optimisticAsserter must revert.
        // msg.sender of these calls is this test contract, which is never the
        // immutable optimisticAsserter address of a freshly deployed c.
        bool reverted;
        try c.assertionResolvedCallback(assertionId, truthfully) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);

        bool reverted2;
        try c.assertionDisputedCallback(assertionId) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assert(reverted2);

        // policy is always the all-false default
        C.AssertionPolicy memory p = c.getAssertionPolicy(assertionId);
        assert(!p.blockAssertion && !p.arbitrateViaEscalationManager && !p.discardOracle && !p.validateDisputers);
    }
    receive() external payable {}
}

