contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData,
        address fakeCaller
    ) public {
        require(fakeCaller != address(this), "need distinct fake caller");

        // Non-asserter call must revert (a fresh contract address is never the optimisticAsserter).
        bool fakeReverted;
        (bool ok1, ) = fakeCaller.call(
            abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData)
        );
        fakeReverted = !ok1;

        // Legitimate call from this contract (msg.sender of c's deployment is this test contract,
        // which equals msg.sender == optimisticAsserter's caller only if optimisticAsserter == c itself;
        // instead we rely on revert semantics: attempt and record).
        bool selfReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            selfReverted = false;
        } catch {
            selfReverted = true;
        }

        // Whichever way the asserter-path call went, non-asserter calls must always revert
        // and the asserter-path must consistently succeed when the asserter is c itself.
        assert(
            fakeReverted == true &&
            selfReverted == (address(c.optimisticAsserter()) != address(this))
        );
    }

    receive() external payable {}
}

